import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

// 플랫 데이터를 트리 구조로 변환
function buildTree(data) {
  if (!data || data.length === 0) return [];

  const deptMap = new Map();
  const membersByDept = new Map();

  data.forEach(row => {
    if (!deptMap.has(row.department_id)) {
      deptMap.set(row.department_id, {
        id: row.department_id,
        name: row.department_name,
        code: row.department_code,
        parentId: row.parent_id,
        depth: row.depth,
        children: [],
        members: []
      });
    }

          if (row.member_id) {
      if (!membersByDept.has(row.department_id)) {
        membersByDept.set(row.department_id, []);
      }
      membersByDept.get(row.department_id).push({
        id: row.member_id,
        userId: row.user_id,
        name: row.member_name,
        memberType: row.member_type,
        employeeNumber: row.employee_number,
        mobile: row.mobile_number,
        profileImage: row.profile_image_path,
        order: row.member_sort_order
      });
    }
  });

  membersByDept.forEach((members, deptId) => {
    if (deptMap.has(deptId)) {
      deptMap.get(deptId).members = members;
    }
  });

  const tree = [];
  deptMap.forEach(dept => {
    if (dept.parentId === null) {
      tree.push(dept);
    } else if (deptMap.has(dept.parentId)) {
      deptMap.get(dept.parentId).children.push(dept);
    }
  });

  return tree;
}

// 부서 노드 컴포넌트
function DepartmentNode({ dept, expandAll }) {
  const [isExpanded, setIsExpanded] = React.useState(false);
  const hasChildren = dept.children && dept.children.length > 0;
  const hasMembers = dept.members && dept.members.length > 0;

  React.useEffect(() => {
    setIsExpanded(expandAll);
  }, [expandAll]);

  return React.createElement("div", { className: "dept-node" },
    React.createElement("div", { 
      className: "dept-header", 
      onClick: () => setIsExpanded(!isExpanded) 
    },
      React.createElement("span", { className: "expand-icon" }, 
        (hasChildren || hasMembers) ? (isExpanded ? "▼" : "▶") : "○"
      ),
      React.createElement("span", { className: "dept-name" }, dept.name),
      React.createElement("span", { className: "dept-code" }, `(${dept.code || "-"})`),
      hasMembers && React.createElement("span", { className: "member-count" }, `${dept.members.length}명`)
    ),
    isExpanded && React.createElement("div", { className: "dept-content" },
      hasMembers && dept.members.map(member =>
        React.createElement("div", { key: member.id, className: "member-item" },
          "👤 ",
          member.name || `User #${member.userId}`,
          member.employeeNumber && React.createElement("span", { className: "employee-number" }, ` (${member.employeeNumber})`),
          member.memberType && React.createElement("span", { className: "member-type" }, `[${member.memberType}]`)
        )
      ),
      hasChildren && dept.children.map(child =>
        React.createElement(DepartmentNode, { key: child.id, dept: child, expandAll })
      )
    )
  );
}

// 메인 App 컴포넌트
function App() {
  const [tree, setTree] = React.useState([]);
  const [expandAll, setExpandAll] = React.useState(false);

  React.useEffect(() => {
    const data = appsmith.model.data;
    console.log("Raw data:", data);
    setTree(buildTree(data));
  }, [appsmith.model.data]);

  return React.createElement("div", { className: "org-chart" },
    React.createElement("div", { className: "chart-header" },
      React.createElement("h2", null, "🏢 조직도"),
      React.createElement("button", { 
        className: "expand-btn", 
        onClick: () => setExpandAll(!expandAll) 
      }, expandAll ? "모두 접기" : "모두 펼치기")
    ),
    tree.length === 0
      ? React.createElement("div", { className: "empty-state" }, "데이터가 없습니다.")
      : tree.map(dept => 
          React.createElement(DepartmentNode, { key: dept.id, dept, expandAll })
        )
  );
}

appsmith.onReady(() => {
  ReactDOM.render(React.createElement(App), document.getElementById("root"));
});
</script>

